import{c as t,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const k=JSON.parse('{"title":"用 Skill 建構驗證迴圈（Verification Loops）","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/47-verification-loops-skills.md","filePath":"research/best-practices/47-verification-loops-skills.md","lastUpdated":1785909234000}'),i={name:"research/best-practices/47-verification-loops-skills.md"};function d(l,e,c,s,n,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="用-skill-建構驗證迴圈-verification-loops" tabindex="-1">用 Skill 建構驗證迴圈（Verification Loops） <a class="header-anchor" href="#用-skill-建構驗證迴圈-verification-loops" aria-label="Permalink to &quot;用 Skill 建構驗證迴圈（Verification Loops）&quot;">​</a></h1><blockquote><p>來源：<a href="https://claude.com/blog/building-verification-loops-in-claude-code-with-skills" target="_blank" rel="noreferrer">Building verification loops in Claude Code with skills</a>（2026-07-22） 整理日期：2026-08-04</p></blockquote><hr><h2 id="定義" tabindex="-1">定義 <a class="header-anchor" href="#定義" aria-label="Permalink to &quot;定義&quot;">​</a></h2><blockquote><p>驗證迴圈 = agent 檢查自己的產出（跑測試、linter 或自訂檢查）並在往下走之前修好失敗項的<strong>重複循環</strong>。</p></blockquote><p>重點在「自己閉環」：把你<strong>反覆手動執行</strong>的品質檢查編碼成 Skill，Claude 就能在無人介入下迭代。</p><hr><h2 id="內建驗證能力" tabindex="-1">內建驗證能力 <a class="header-anchor" href="#內建驗證能力" aria-label="Permalink to &quot;內建驗證能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>機制</th><th>說明</th></tr></thead><tbody><tr><td><code>/verify</code> skill</td><td>內建驗證流程（v2.1.215 起<strong>不再由 Claude 自行觸發</strong>，需手動呼叫）</td></tr><tr><td>Toolchain 整合</td><td>linter、type checker 直接由 agent 執行</td></tr><tr><td>Code Review</td><td>PR 層級審查（<code>/code-review</code>，v2.1.215 起同樣改為手動呼叫）</td></tr><tr><td>GitHub Actions</td><td>CI 端自動化</td></tr><tr><td>Spec validation / rubrics</td><td>Managed agents 的評分準則</td></tr></tbody></table><hr><h2 id="自訂驗證-skill-的寫法" tabindex="-1">自訂驗證 Skill 的寫法 <a class="header-anchor" href="#自訂驗證-skill-的寫法" aria-label="Permalink to &quot;自訂驗證 Skill 的寫法&quot;">​</a></h2><ol><li>最快路徑：用 <code>skill-creator</code> plugin 產生骨架。</li><li>手寫：在 <code>.claude/skills/</code> 放 markdown，frontmatter 給 <code>name</code> / <code>description</code> / <code>allowed-tools</code>，正文用<strong>白話的程序描述</strong>（不是程式碼）。</li><li>判準：<strong>專案特定的確定性規則</strong>就是驗證迴圈的素材——例如「拒絕會 drop column 但沒有 backfill 的 migration」。凡是你會反覆人工把關的事，都該編碼。</li></ol><hr><h2 id="四種部署形態" tabindex="-1">四種部署形態 <a class="header-anchor" href="#四種部署形態" aria-label="Permalink to &quot;四種部署形態&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形態</th><th>時機</th></tr></thead><tbody><tr><td><strong>Standalone</strong></td><td>跨切面檢查，刻意手動呼叫</td></tr><tr><td><strong>Embedded</strong></td><td>內嵌在產出型 Skill 裡，產完自動驗</td></tr><tr><td><strong>Chained</strong></td><td>一個 Skill 觸發另一個</td></tr><tr><td><strong>PR-wide</strong></td><td>團隊基礎建設，套用到所有變更</td></tr></tbody></table><p>演進路徑：個人生產力工具（standalone）→ 鏈式自動化 → PR gate，讓標準不再依賴個人自律。</p><hr><h2 id="與本-workspace-的關係" tabindex="-1">與本 workspace 的關係 <a class="header-anchor" href="#與本-workspace-的關係" aria-label="Permalink to &quot;與本 workspace 的關係&quot;">​</a></h2><ul><li><code>core.md</code> §TEST 的 <code>unverified_success</code> 閘門與「Oracle 先驗」是同一件事的更嚴格版本：官方講「自己檢查自己」，本 workspace 額外要求 <strong>verifier 為異 instance、只回 PASS/FAIL、不得動手修</strong>，且<strong>確定性 gate 由 parent 親跑</strong>。</li><li><code>review-hub</code> / <code>security-reviewer</code> / <code>.githooks/pre-commit</code> 即本 workspace 的 standalone 與 PR-wide 形態。</li><li>官方新增的「Claude 不再自行呼叫 <code>/verify</code>、<code>/code-review</code>」（v2.1.215）意味著<strong>驗證的觸發責任回到 harness</strong>——本 workspace 的 SKILL 與 hook 需明確呼叫，不能假設模型自動跑。</li></ul><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>06-agent-skills-best-practices.md</code> — Skill 撰寫原則</li><li><code>22-code-review.md</code> — 多代理 PR 審查</li><li><code>48-w28-w31-features.md</code> — v2.1.215 / v2.1.218 對 <code>/verify</code>、<code>/code-review</code>、<code>/deep-research</code> 自動觸發的收斂</li></ul>',22)])])}const u=t(i,[["render",d]]);export{k as __pageData,u as default};
